package android.content;import java.util.*; public class SharedPreferences { public Map<String,Object> data=new HashMap<>();public boolean fail;public boolean getBoolean(String k,boolean d){return (Boolean)data.getOrDefault(k,d);}public String getString(String k,String d){return (String)data.getOrDefault(k,d);}public Editor edit(){return new Editor();}public class Editor {Map<String,Object> pending=new HashMap<>();public Editor putBoolean(String k,boolean v){pending.put(k,v);return this;}public boolean commit(){if(fail)return false;data.putAll(pending);return true;}} }